import {createW05RescueComposition,W05_RESCUE_SURFACES} from '../../../surfaces/composition/w05-rescue.js';
import {ProcessingRuntimeAdapter} from '../../../adapters/processing-runtime.js';
import {ProviderAwareBackupIntegrationAdapter} from '../../../adapters/backup-runtime.js';
import {DurableAuditRuntimeAdapter} from '../../../adapters/audit.js';
import {SemanticCommandBus} from '../../../foundation/global/commands.js';
const assert=(v,m)=>{if(!v)throw Error(m)};
class QueueTransport{constructor(responses=[]){this.responses=[...responses];this.calls=[];}descriptor(){return {id:'CG6FakeTransport',semanticOwnership:false};}async request(method,path,body){this.calls.push({method,path,body});const r=this.responses.shift();return structuredClone(typeof r==='function'?r({method,path,body}):(r??{ok:false,code:'NO_RESPONSE'}));}}
const results=[];async function run(id,fn){try{await fn();results.push({id,status:'PASS'});}catch(error){results.push({id,status:'FAIL',error:String(error?.message||error)});}}

await run('cg6.composition-eight-surfaces-and-no-final-wiring',async()=>{const c=createW05RescueComposition({transport:new QueueTransport(),commands:new SemanticCommandBus()});assert(JSON.stringify(c.surfaceIds)===JSON.stringify(W05_RESCUE_SURFACES),'surface set drift');assert(Object.keys(c.surfaces).length===8,'eight surfaces required');assert(c.finalR6Wiring===false&&c.balanced6==='HOLD','R6/Balanced6 boundary lost');assert(!c.ownership.duplicatePersistenceOwner&&!c.ownership.duplicateProviderOwner&&!c.ownership.surfaceSemanticsMovedIntoProviders,'duplicate owner/provider semantics detected');});
await run('cg6.processing-retry-explicit-durable-idempotency-key',async()=>{const failed={jobId:'job-1',requestId:'request-1',correlationId:'corr-1',inputDigest:'d',taskKind:'SHA256_JSON',state:'FAILED',lifecycleVersion:1,currentAttemptId:'attempt-1',attemptIds:['attempt-1'],attempts:[{attemptId:'attempt-1',state:'FAILED'}]};const t=new QueueTransport([{ok:true,jobs:[failed]},{ok:false,code:'RETRY_NOT_ALLOWED'}]);const a=new ProcessingRuntimeAdapter({transport:t});await a.refresh();await a.retry();const call=t.calls.at(-1);assert(call.body.idempotencyKey==='retry:job-1:attempt-1','retry idempotency key not explicit/stable');});
await run('cg6.backup-provider-preview-conflict-blocks-stage',async()=>{const pkg={ok:true,status:'PACKAGE_VERIFIED',packageId:'pkg-1',manifestSha256:'m',snapshotSha256:'s',schemaArtifactSha256:'a',capturedAt:'2026-09-18T00:00:00Z',correlationId:'corr-b'};const t=new QueueTransport([pkg,{ok:true,attempts:[{attemptId:'a1',operation:'PACKAGE',status:'SUCCEEDED'}]},{ok:false,code:'PACKAGE_TARGET_SCHEMA_CONFLICT',status:'SCHEMA_CONFLICT',writeEffects:{stageWrites:0,drillWrites:0,activationWrites:0,productionDatabaseWrites:0,liveRestoreWrites:0}}]);const a=new ProviderAwareBackupIntegrationAdapter({transport:t});await a.createPackage();a.plan();const p=await a.preview();assert(!p.ok&&p.status==='SCHEMA_CONFLICT','schema conflict not preserved');const s=await a.stage();assert(!s.ok&&s.code==='PROVIDER_PREVIEW_REQUIRED','stage should be blocked after conflict');assert(!t.calls.some(c=>c.path==='/v1/backup/stage'),'stage provider called after conflict');});
await run('cg6.backup-durable-attempt-journal-and-no-live-restore',async()=>{const pkg={ok:true,status:'PACKAGE_VERIFIED',packageId:'pkg-1',manifestSha256:'m',snapshotSha256:'s',schemaArtifactSha256:'a',capturedAt:'2026-09-18T00:00:00Z',correlationId:'corr-b'};const preview={ok:true,status:'PREVIEW_OK',writeEffects:{stageWrites:0,drillWrites:0,activationWrites:0,productionDatabaseWrites:0,liveRestoreWrites:0}};const stage={ok:true,status:'STAGED',packageId:'pkg-1',productionDatabaseMutated:false,liveRestored:false};const attempts={ok:true,attempts:[{attemptId:'a1',operation:'PACKAGE_STAGE',status:'SUCCEEDED',originalError:null,compensation:null}]};const t=new QueueTransport([pkg,{ok:true,attempts:[]},preview,stage,attempts]);const a=new ProviderAwareBackupIntegrationAdapter({transport:t});await a.createPackage();a.plan();await a.preview();const s=await a.stage();assert(s.liveRestored===false&&s.productionDatabaseMutated===false,'stage fabricated live restore');assert(a.truth().durableFailureCompensationHistory==='PROVIDER_DURABLE_ATTEMPT_JOURNAL','provider attempt journal not bound');});
await run('cg6.audit-durable-provider-first-invalid-and-separate-annotation',async()=>{const t=new QueueTransport([{ok:true,events:[{sequence:1,eventId:'e1',actor:'x',action:'a',target:'t',outcome:'SUCCESS',correlationId:'c',hash:'h',previousHash:'GENESIS'}],pagination:{nextCursor:null}},{ok:true,valid:false,firstInvalidSequence:1,observedScope:{count:1,watermarkHash:'h'}},{ok:true,annotation:{annotationId:'n1',eventId:'e1',revision:1},eventMutated:false}]);const a=new DurableAuditRuntimeAdapter({transport:t});await a.search({limit:50});await a.verify();await a.annotate({eventId:'e1',note:'note'});const truth=a.truth();assert(truth.persistence==='PROVIDER_DURABLE_JSONL','audit not durable provider-backed');assert(truth.firstInvalidSequence===1,'first-invalid sequence lost');assert(truth.commandReceiptsAreAuditTruth===false&&truth.hashIsEncryption===false&&truth.databaseImmutabilityClaim===false&&truth.annotationsSeparate===true,'audit truth ceiling lost');});
await run('cg6.truth-ceilings-four-planes-separated',async()=>{const c=createW05RescueComposition({transport:new QueueTransport(),commands:new SemanticCommandBus()});const t=c.truthCeilings;assert(t.processingCompletedNeedsProviderEvidence&&t.cancelRequestIsCancelSuccess===false,'processing truth collapsed');assert(t.backupStageVerifyDrillIsLiveRestore===false&&t.backupActivationAuthorityPendingOnly,'backup truth collapsed');assert(t.auditCommandReceiptsAreAuditEvents===false&&t.auditHashIsEncryption===false,'audit truth collapsed');assert(t.releaseReadinessIsAuthorization===false&&t.releaseAuthorizationIsDeployment===false,'release truth collapsed');});
const summary={total:results.length,pass:results.filter(x=>x.status==='PASS').length,fail:results.filter(x=>x.status==='FAIL').length};globalThis.CG6W05CoverageTests={status:summary.fail?'FAIL':'PASS',summary,results};console.log(JSON.stringify(globalThis.CG6W05CoverageTests,null,2));if(summary.fail)process.exitCode=1;
